import{f as d,D as s,o as n,c as a,ar as i,b as l,w as t,a as m,G as o,aq as g}from"./chunks/framework.W_ryyXug.js";const w=JSON.parse('{"title":"Kurzbefehle für die Erfassung","description":"","frontmatter":{},"headers":[],"relativePath":"dse/stimmzettelerfassung/index.md","filePath":"dse/stimmzettelerfassung/index.md"}'),h={name:"dse/stimmzettelerfassung/index.md"};function u(c,e,b,p,z,f){const r=s("Mermaid");return n(),a("div",null,[e[1]||(e[1]=i('<h1 id="kurzbefehle-fur-die-erfassung" tabindex="-1">Kurzbefehle für die Erfassung <a class="header-anchor" href="#kurzbefehle-fur-die-erfassung" aria-label="Permalink to &quot;Kurzbefehle für die Erfassung {#kurzbefehle-fur-die-erfassung}&quot;">​</a></h1><p>Um eine schnelle Erfassung der Daten des Stimmzettels zu ermöglichen, können Befehle eingegeben werden.</p><h2 id="uberblick-befehle" tabindex="-1">Überblick Befehle <a class="header-anchor" href="#uberblick-befehle" aria-label="Permalink to &quot;Überblick Befehle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Befehl</th><th>Funktion</th><th>Beispiel</th></tr></thead><tbody><tr><td><strong>Einzelstimmen</strong></td><td></td><td></td></tr><tr><td><code>&lt;Kandidatenordnungszahl&gt;</code></td><td>Fügt eine Stimme bei dem/der Kandidat*in mit der <code>Ordnungszahl</code> hinzu</td><td>101</td></tr><tr><td><code>&lt;Kandidatenordnungszahl&gt;+</code></td><td>Fügt eine Stimme bei dem/der Kandidat*in mit der <code>Ordnungszahl</code> hinzu</td><td>101+</td></tr><tr><td><code>&lt;Kandidatenordnungszahl&gt;+&lt;n&gt;</code></td><td>Fügt <code>n</code> Stimmen bei dem/der Kandidat*in mit der <code>Ordnungszahl</code> hinzu</td><td>101+3</td></tr><tr><td><code>&lt;Kandidatenordnungszahl&gt;-</code></td><td>Entfernt eine Stimme bei dem/der Kandidat*in mit der <code>Ordnungszahl</code></td><td>101-</td></tr><tr><td><code>&lt;Kandidatenordnungszahl&gt;-&lt;n&gt;</code></td><td>Entfernt <code>n</code> Stimmen bei dem/der Kandidat*in mit der <code>Ordnungszahl</code></td><td>101-3</td></tr><tr><td><code>[u/U]&lt;Kandidatenordnungszahl&gt;</code></td><td>Fügt 1 ungültige Stimme bei dem/der Kandidat*in mit der <code>Ordnungszahl</code> hinzu</td><td>u101</td></tr><tr><td><code>[u/U]&lt;Kandidatenordnungszahl&gt;+&lt;n&gt;</code></td><td>Fügt <code>n</code> ungültige Stimmen bei dem/der Kandidat*in mit der <code>Ordnungszahl</code> hinzu</td><td>u101+3</td></tr><tr><td><code>[u/U]&lt;Kandidatenordnungszahl&gt;-</code></td><td>Entfernt 1 ungültige Stimme bei dem/der Kandidat*in mit der <code>Ordnungszahl</code></td><td>u101-</td></tr><tr><td><code>[u/U]&lt;Kandidatenordnungszahl&gt;-&lt;n&gt;</code></td><td>Entfernt <code>n</code> ungültige Stimmen bei dem/der Kandidat*in mit der <code>Ordnungszahl</code></td><td>u101-3</td></tr><tr><td><code>&lt;untere&gt;-&lt;obere&gt;</code></td><td>Fügt je 1 Stimme bei allen Kandidat*innen im Bereich der <code>Ordnungszahl</code> von <code>untere</code>–<code>obere</code> hinzu</td><td>501-510</td></tr><tr><td><code>&lt;untere&gt;-&lt;obere&gt;+&lt;n&gt;</code></td><td>Fügt je <code>n</code> Stimmen im Bereich der <code>Ordnungszahl</code> von <code>untere</code>–<code>obere</code> hinzu</td><td>527-535+2</td></tr><tr><td><strong>Listenkreuze</strong></td><td></td><td></td></tr><tr><td><code>&lt;Wahlvorschlagsnummer&gt;</code></td><td>Kennzeichnet den Wahlvorschlag mit der <code>Ordnungszahl</code> (Die Eingabe erfolgt entweder als Wahlvorschlagsnummer oder als Ordnungszahl mit „00“ am Ende)</td><td>5, 500</td></tr><tr><td><code>&lt;Wahlvorschlagsnummer&gt;-</code></td><td>Entfernt die Kennzeichnung des Wahlvorschlags mit der <code>Ordnungszahl</code> (Die Eingabe erfolgt entweder als Wahlvorschlagsnummer oder als Ordnungszahl mit „00“ am Ende)</td><td>5-, 500-</td></tr><tr><td><strong>Streichungen</strong></td><td></td><td></td></tr><tr><td><code>[s/S]&lt;Kandidatenordnungszahl&gt;</code></td><td>Streichung für den/die Kandidat*in mit der <code>Ordnungszahl</code></td><td>s501</td></tr><tr><td><code>[s/S]&lt;untere&gt;-&lt;obere&gt;</code></td><td>Streichungen für alle Kandidat*innen im Bereich der <code>Ordnungszahl</code> von <code>untere</code>–<code>obere</code></td><td>s501-509</td></tr><tr><td><code>[s/S]&lt;Kandidatenordnungszahl&gt;-</code></td><td>Streichung für den/die Kandidat*in mit der <code>Ordnungszahl</code> wird zurückgenommen</td><td>s501-</td></tr><tr><td><code>[s/S]&lt;untere&gt;-&lt;obere&gt;-</code></td><td>Streichungen für alle Kandidat*innen im Bereich der <code>Ordnungszahl</code> von <code>untere</code>–<code>obere</code> werden zurückgenommen</td><td>s501-509-</td></tr></tbody></table><h2 id="ausfuhrliche-beschreibung" tabindex="-1">Ausführliche Beschreibung <a class="header-anchor" href="#ausfuhrliche-beschreibung" aria-label="Permalink to &quot;Ausführliche Beschreibung&quot;">​</a></h2><h3 id="eingabeformat-und-allgemeine-regeln" tabindex="-1">Eingabeformat und allgemeine Regeln <a class="header-anchor" href="#eingabeformat-und-allgemeine-regeln" aria-label="Permalink to &quot;Eingabeformat und allgemeine Regeln&quot;">​</a></h3><p>Ein Befehl wird ohne Leerzeichen eingegeben und durch die Betätigung der <code>Enter</code>-Taste ausgeführt. Bei <code>u</code> für ungültige Stimmen und <code>s</code> für Streichungen spielt die Groß- und Kleinschreibung keine Rolle.</p><ul><li><code>&lt;Kandidatenordnungszahl&gt;</code> ist die auf dem Stimmzettel angegebene Ordnungszahl eines/einer Kandidat*in, zum Beispiel <code>101</code>. Im Folgenden ist sie mit der <code>Listenposition</code> gleichzusetzen.</li><li><code>&lt;Wahlvorschlagsnummer&gt;</code> ist die Nummer eines Wahlvorschlags, zum Beispiel <code>5</code>. Alternativ kann die zugehörige Ordnungszahl mit zwei Nullen verwendet werden, in diesem Fall <code>500</code>.</li><li><code>&lt;n&gt;</code> ist eine positive ganze Zahl. Fehlt die Anzahl bei einem <code>+</code> oder <code>-</code>, geht das System automatisch von einer <code>1</code> aus. Dementsprechend haben beispielsweise <code>101</code> und <code>101+</code> dieselbe Wirkung.</li><li>Ein Bereich enthält die untere und obere Grenze: <code>501-510</code> betrifft die Kandidatenordnungszahlen 501 bis einschließlich 510. Die Reihenfolge der Grenzen ist unerheblich, daher wirkt <code>510-501</code> genauso wie <code>501-510</code>.</li></ul><h3 id="kandidat-innenstimmen" tabindex="-1">Kandidat*innenstimmen <a class="header-anchor" href="#kandidat-innenstimmen" aria-label="Permalink to &quot;Kandidat\\*innenstimmen&quot;">​</a></h3><h4 id="einzelstimmen" tabindex="-1">Einzelstimmen <a class="header-anchor" href="#einzelstimmen" aria-label="Permalink to &quot;Einzelstimmen&quot;">​</a></h4><p>Für Befehle zu einzelnen Kandidat*innen muss die angegebene Kandidatenordnungszahl auf dem Stimmzettel vorhanden sein. Beim Entfernen von Stimmen muss die Menge der zu entfernenden Stimmen bereits vergeben worden sein.</p><p>Überschreitet die eingegebene Stimmenzahl die je Kandidat*in zulässige Höchstzahl, wird der Befehl nicht abgelehnt. Das System erfasst den zulässigen Anteil als gültige Einzelstimmen und den darüber hinausgehenden Anteil als ungültige Stimmen. Alternativ können ungültige Stimmen auch manuell erfasst werden.</p><p>Beim Entfernen gültiger Stimmen wird dabei die Summe der gültigen und ungültigen Stimmen der ausgewählten Nennung berücksichtigt. Das System entfernt zuerst vorhandene ungültige Stimmen und danach gültige Einzelstimmen. Ungültige Stimmen können nur entfernt werden, wenn mindestens die angegebene Menge an ungültigen Stimmen vorhanden ist.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Einzelstimmen</p><p>Bei einer Wahl dürfen je Kandidat*in maximal 3 Stimmen vergeben werden. Der/die Wähler*in hat eine 5 bei einem/einer Kandidat*in eingetragen.</p><p>Es wurden 5 Stimmen vergeben, davon sind 3 gültig und 2 vom System automatisch als ungültig erkannt.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Entfernen von Einzelstimmen</p><p>Bei einer Wahl dürfen je Kandidat*in maximal 3 Stimmen vergeben werden. Der/die Wähler*in hat eine 5 bei einem/r Kandidat*in eingetragen und möchte nun 3 davon wieder entfernen.</p><p>Es sind 3 gültige und 2 ungültige Stimmen vorhanden. Nach der Entfernung von 3 Stimmen, angefangen bei den ungültigen, sind noch 2 gültige Stimmen übrig.</p></div></details><h4 id="streichungen" tabindex="-1">Streichungen <a class="header-anchor" href="#streichungen" aria-label="Permalink to &quot;Streichungen&quot;">​</a></h4><p>Eine Streichung kann nur gesetzt werden, wenn mindestens eine Nennung des/der gewählten Kandidat*in noch nicht gestrichen ist. Sie kann nur zurückgenommen werden, wenn eine Streichung vorhanden ist. Wird eine Streichung gesetzt, werden bereits erfasste gültige Einzelstimmen dieser Nennung zu ungültigen Stimmen. Ebenso werden Stimmen, die zu einer bereits gestrichenen Nennung hinzugefügt werden, als ungültige Stimmen erfasst.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen einer Streichung, obwohl Stimmen vergeben wurden</p><p>Es gibt Kandidat*innen mit den Listenpositionen 1 bis 10. Die Position 2 hat bereits 3 Einzelstimmen. Der/die Wähler*in vergibt nun eine Streichung für diese Position.</p><p>Die zuvor gültigen Stimmen werden vom System automatisch als 3 ungültige Stimmen erkannt und der/die Kandidat*in ist gestrichen.</p></div></details><div class="important custom-block github-alert"><p class="custom-block-title">Entfernen einer Streichung wandelt ungültige Stimmen nicht in gültige um</p><p>Wenn ein/e Kandidat*in mit 3 Einzelstimmen gestrichen wird, werden diese gültigen Stimmen in ungültige umgewandelt. Wird die Streichung nun wieder entfernt bleiben die Stimmen ungültig und müssen ggf. manuell wieder zu gültigen gemacht werden.</p></div><h4 id="bereiche" tabindex="-1">Bereiche <a class="header-anchor" href="#bereiche" aria-label="Permalink to &quot;Bereiche&quot;">​</a></h4><p>Ein Bereich kann nur Kandidatenordnungszahlen eines Wahlvorschlags enthalten. Für einen Bereich müssen alle Ordnungszahlen zwischen unterer und oberer Grenze auf dem Stimmzettel vorhanden sein. Fehlt auch nur eine Ordnungszahl oder umfasst der Bereich mehrere Wahlvorschläge, wird der gesamte Befehl abgelehnt. Ein Stimmenbereich kann außerdem nur ausgeführt werden, wenn keine darin enthaltene Nennung gestrichen ist. Bereits erfasste Stimmen bleiben dabei unverändert, beziehungsweise werden durch die Bereichsstimmen ergänzt.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Ungültiger Bereich über Grenze hinweg</p><p>Ein Wahlvorschlag enthält die Kandidatenordnungszahlen 501 bis 505.</p><p>Der Befehl 501-510 wird abgelehnt, weil die Ordnungszahlen 506 bis 510 nicht existieren.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Ungültiger Bereich über Wahlvorschläge hinweg</p><p>Es existieren die Wahlvorschläge mit den Ordnungszahlen 100 und 200.</p><p>Der Befehl 101-201 wird abgelehnt, weil die Ordnungszahlen 101 und 201 zu unterschiedlichen Wahlvorschlägen gehören.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Ungültiger Bereich, weil Streichung vorhanden</p><p>Es gibt die Listenpositionen 1 bis 10. Die Position 2 ist bereits gestrichen worden. Der/die Wähler*in vergibt nun jeweils 2 Stimmen für den Bereich 1-3.</p><p>Der Befehl wird abgelehnt.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Bereichsstimmen zu bestehenden Einzelstimmen</p><p>Es gibt die Listenpositionen 1 bis 10. Die Positionen 1 bis 3 und Position 6 haben bereits eine Einzelstimme erhalten. Der/die Wähler*in vergibt nun jeweils 2 Stimmen für den Bereich 1-3.</p><p>Die Positionen 1-3 haben nun insgesamt jeweils 3 Stimmen, während Position 6 immer noch 1 Stimme hat.</p></div></details><p>Bei einem Streichungsbereich dürfen einzelne Nennungen bereits gestrichen sein: Das System streicht die übrigen Nennungen. Erst wenn alle Nennungen im Bereich bereits gestrichen sind, wird der Befehl abgelehnt. Entsprechend wird das Zurücknehmen eines Streichungsbereichs nur abgelehnt, wenn im gesamten Bereich keine Streichung vorhanden ist.</p><h4 id="mehrfachnennungen" tabindex="-1">Mehrfachnennungen <a class="header-anchor" href="#mehrfachnennungen" aria-label="Permalink to &quot;Mehrfachnennungen&quot;">​</a></h4><p>Ist ein/eine Kandidat*in mehrfach auf dem Stimmzettel genannt, haben diese Nennungen dieselbe Kandidatenordnungszahl. Bei einem Befehl für eine einzelne Kandidatenordnungszahl wählt das System eine passende Nennung automatisch aus: beim Hinzufügen von Stimmen werden Nennungen mit bereits vorhandenen Einzelstimmen bevorzugt; andernfalls wird eine nicht gestrichene Nennung gewählt. Beim Entfernen wird eine Nennung bevorzugt, auf der die zu entfernenden Stimmen oder die Streichung vorhanden sind. Ein Befehl kann sich immer nur auf eine einzelne Nennung beziehen.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Stimmen</p><p>Es gibt die Listenpositionen 1 bis 10, jeweils in dreifacher Nennung. Kandidat*in 102 hat bereits 2 Stimmen bei der ersten Nennung und der/die Wähler*in möchte eine weitere Einzelstimme eintragen.</p><p>Die erste Nennung von Kandidat*in 102 hat jetzt 3 Stimmen.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Stimmen mit vorhandener Streichung</p><p>Es gibt die Listenpositionen 1 bis 10, jeweils in dreifacher Nennung. Kandidat*in 102 hat bereits eine Streichung bei der ersten Nennung und der/die Wähler*in möchte eine weitere Einzelstimme eintragen.</p><p>Die erste Nennung von Kandidat*in 102 ist weiterhin gestrichen und die zweite Nennung hat 1 Stimme.</p><p>Hinweis: Analog wird bei umgedrehter Ausgangslage bei einem/r Kandidat*in mit vorhandenen Stimmen bei Nennung 1 die zweite Nennung gestrichen.</p></div></details><p>Ein Bereichsbefehl betrifft dagegen alle Nennungen jeder enthaltenen Kandidatenordnungszahl.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Bereichsstimmen</p><p>Es gibt die Listenpositionen 1 bis 10, jeweils in zweifacher Nennung. Es dürfen je Kandidat*in maximal 3 Stimmen vergeben werden. Der/die Wähler*in vergibt nun jeweils 2 Stimmen für den Bereich 1-3.</p><p>Die Positionen 1 bis 3 haben jeweils 2 gültige Stimmen bei der ersten Nennung und eine gültige sowie eine ungültige Stimme bei der zweiten Nennung.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Ergänzen von Bereichsstimmen zu bestehenden Einzelstimmen</p><p>Es gibt die Listenpositionen 1 bis 10, jeweils in zweifacher Nennung. Es dürfen je Kandidat*in maximal 3 Stimmen vergeben werden. Die Position 1 hat bereits 2 Einzelstimmen für die erste Nennung erhalten. Der/die Wähler*in vergibt nun jeweils 2 Stimmen für den Bereich 1-3.</p><p>Die Position 1 hat nun insgesamt 6 Stimmen, davon sind 3 gültige und eine ungültige bei der ersten Nennung und 2 ungültige bei der zweiten Nennung.<br> Die Positionen 2 und 3 haben jeweils 2 gültige Stimmen bei der ersten Nennung und eine gültige sowie eine ungültige Stimme bei der zweiten Nennung.</p></div></details><div class="important custom-block github-alert"><p class="custom-block-title">Entfernen von Stimmen bei Mehrfachnennungen</p><p>Wurden mehreren Nennungen eines/einer Kandidat*in per Bereichsvergabe mit Stimmen versehen, können diese nicht ebenso per Bereich wieder entfernt werden. Stattdessen müssen die Stimmen pro Nennung einzeln entfernt werden. Dabei fängt das System immer mit der ersten Nennung an, bei welcher Stimmen vergeben wurden.</p></div><h3 id="wahlvorschlage" tabindex="-1">Wahlvorschläge <a class="header-anchor" href="#wahlvorschlage" aria-label="Permalink to &quot;Wahlvorschläge&quot;">​</a></h3><p>Für das Setzen von einem Listenkreuz muss der angegebene Wahlvorschlag vorhanden sein. Ein Listenkreuz kann nur gesetzt werden, wenn der Wahlvorschlag noch nicht ausgewählt ist, und nur entfernt werden, wenn er ausgewählt ist.</p><p>Wenn bei einem Wahlvorschlag ein Listenkreuz gesetzt wird, werden Stimmen über die sogenannte Reststimmenvergabe verteilt. Dabei werden die Stimmen der Reihe nach auf die Kandidat*innen des Wahlvorschlags verteilt, die sonst noch keine Kennzeichen (Stimmen oder Streichung) erhalten haben.</p><p>Grundsätzlich gilt, dass die Vergabe nur erfolgt, wenn eine eindeutige Vergabe möglich ist. Es können nur so viele Stimmen vergeben werden, wie nicht explizit durch den/die Wähler*in vergeben wurden. Die Menge der bereits vergebenen Stimmen ergibt sich aus der Summe der vergebenen Einzelstimmen und sonstigen ungültigen Stimmen.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Reststimmenmenge bei vorhandenen Einzelstimmen</p><p>Bei einer Wahl können bis zu 40 Stimmen vergeben werden. Der/die Wähler*in hat 3 Kreuze bei unterschiedlichen Kandidat*innen gesetzt und bei einem/einer weiteren eine 2 eingetragen.</p><p>Somit sind 5 Stimmen vergeben, und für die Reststimmenvergabe stehen noch 35 Stimmen zur Verfügung.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Unerlaubterweise wurde ein/eine zusätzliche/r Kandidat\\*in ergänzt</p><p>Bei einer Wahl können bis zu 40 Stimmen vergeben werden. Der/die Wähler*in hat 3 Kreuze bei unterschiedlichen Kandidat*innen gesetzt. Zusätzlich wurde ein/eine weitere/r Kandidat*in ergänzt mit der Zahl 3 davor. Somit sind 6 Stimmen vergeben, wobei 3 gültig sind und 3 ungültig.</p><p>Für die Reststimmenvergabe stehen noch 34 Stimmen zur Verfügung.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Reststimmenmenge bei zu vielen Einzelstimmen bei einem/einer Kandidat\\*in</p><p>Bei einer Wahl können bis zu 40 Stimmen vergeben werden. Je Kandidat*in dürfen maximal 3 Stimmen vergeben werden. Der/die Wähler*in hat bei einem/einer Kandidat*in eine 5 eingetragen. Somit sind 5 Stimmen vergeben, wobei 3 gültig sind und 2 ungültig.</p><p>Für die Reststimmenvergabe stehen noch 35 Stimmen zur Verfügung.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Keine Reststimmenvergabe möglich</p><p>Bei einer Wahl können bis zu 40 Stimmen vergeben werden. Der/die Wähler*in hat bei 2 Wahlvorschlägen jeweils das Listenkreuz gesetzt. Je Wahlvorschlag gibt es 40 Kandidat*innen.</p><p>Es erfolgt keine Reststimmenvergabe: Für eine Reststimmenvergabe wären 80 Stimmen notwendig. Somit ist nicht eindeutig erkennbar, wie die Aufteilung der 40 Stimmen auf die 80 Kandidat*innen erfolgen soll.</p></div></details><p>Die Vergabe der Reststimmen erfolgt entsprechend der Listenposition innerhalb des Wahlvorschlags, beginnend bei der ersten Position. Ein/eine Kandidat*in kann nur Reststimmen erhalten, wenn er/sie noch keine Stimmen erhalten hat und er/sie nicht gestrichen wurde. Gibt es für Kandidat*innen mehrere Nennungen, kann ein/eine Kandidat*in außerdem nur Reststimmen bekommen, wenn er/sie noch nicht die maximal erlaubte Menge an Stimmen erreicht hat.</p><details><summary>Beispiele</summary><div class="note custom-block github-alert"><p class="custom-block-title">Reststimmenvergabe bei vorhandener Einzelstimmenvergabe</p><p>Es gibt die Listenpositionen 1 bis 10. Die Positionen 1 bis 3 und Position 6 haben bereits Einzelstimmen erhalten.</p><p>Über die Reststimmenvergabe bekommen die Positionen 4, 7, 8, 9 und 10 jeweils eine Reststimme.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Reststimmenvergabe bei vorhandener Einzelstimmenvergabe und Streichung</p><p>Es gibt die Listenpositionen 1 bis 10. Die Positionen 1 bis 3 haben bereits Einzelstimmen erhalten. Die Position 6 wurde gestrichen.</p><p>Über die Reststimmenvergabe bekommen die Positionen 4, 7, 8, 9 und 10 jeweils eine Reststimme.</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Reststimmenvergabe bei vorhandener Mehrfachnennung</p><p>Es gibt die Listenpositionen 1 bis 10, jeweils in dreifacher Nennung. Je Kandidat*in dürfen maximal 3 Stimmen vergeben werden.</p><p>Die Position 1 hat bei jeder der 3 Nennungen ein Kreuz. Die Position 2 hat bei der ersten Nennung eine 2 stehen.<br> Die Position 3 hat bei den ersten beiden Nennungen eine 2 stehen.<br> Bei Position 4 wurde die erste Nennung gestrichen.</p><p>Über die Reststimmenvergabe bekommt die Position 1 keine Stimmen, weil für den/die Kandidat*in bereits die maximale Menge an Stimmen erreicht ist.<br> Die Position 2 bekommt noch eine Reststimme, womit sie das Maximum an Stimmen erreicht.<br> Die Position 3 bekommt keine Reststimmen, weil für den/die Kandidat*in bereits die maximale Menge an Stimmen überschritten wurde. Eine der 4 Stimmen wird als ungültig gewertet.<br> Die Position 4 bekommt noch 2 Reststimmen. Für die gestrichene Nennung gibt es keine Reststimme.<br> Die restlichen Positionen bekommen jeweils 1 Reststimme pro Nennung.</p></div></details><h2 id="architektur-der-eingabeverarbeitung" tabindex="-1">Architektur der Eingabeverarbeitung <a class="header-anchor" href="#architektur-der-eingabeverarbeitung" aria-label="Permalink to &quot;Architektur der Eingabeverarbeitung&quot;">​</a></h2><p>Ein Befehl wird nur ausgeführt, wenn das Eingabeformat gültig ist und alle fachlichen Bedingungen erfüllt sind. Bei einem Fehler nimmt das System keine Änderung aufgrund dieses Befehls vor. Die Anwendung gibt Feedback, wenn der Befehl nicht ausführbar oder falsch war.</p>',37)),(n(),l(g,null,{default:t(()=>[o(r,{id:"mermaid-511",class:"mermaid my-class",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22Start%3A%20User-Eingabestring%22%5D%20--%3E%20B%7B%22%60_commandHandler.canHandle(command)_%20%3Cbr%2F%3E%3Cbr%2F%3E%20technische%20Pr%C3%BCfung%20des%20Befehls%3A%20%3Cbr%2F%3E%20Eingabe%20ist%20korrekt%20und%20kann%20verarbeitet%20werden%3F%60%22%7D%0A%0A%20%20%20%20B%20--%3E%7Cnein%7C%20C%7B%22Weitere%20Handler%20vorhanden%20%3F%22%7D%0A%20%20%20%20%0A%20%20%20%20C%20--%3E%7C%22ja%20(try%20next%20Handler)%22%7C%20B%0A%20%20%20%20C%20--%3E%7C%22nein%20(command%20not%20found)%22%7C%20D%5B%22throw%20%3Cbr%2F%3E%20UnsupportedCommandError%22%5D%0A%20%20%20%20%0A%20%20%20%20B%20--%3E%7Cja%7C%20F%7B%22%60_commandHandler.handleOrThrow(...)_%20%3Cbr%2F%3E%3Cbr%2F%3E%20fachliche%20Pr%C3%BCfung%20des%20Befehls%3A%20%3Cbr%2F%3E%20Kandidat%2FWahlvorschlag%20existiert%20und%20%C3%84nderung%20erlaubt%3F%60%22%7D%0A%0A%20%20%20%20F%20--%3E%7Cja%7C%20H%5B%22Anpassung%20Datenmodell%20%2B%20%3Cbr%2F%3E%20Update%20der%20Eingabehistorie%22%5D%0A%20%20%20%20F%20--%3E%7Cnein%7C%20J%5B%22throw%20%3Cbr%2F%3E%20CommandExecutionError%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h3 id="mogliche-fehler" tabindex="-1">Mögliche Fehler <a class="header-anchor" href="#mogliche-fehler" aria-label="Permalink to &quot;Mögliche Fehler&quot;">​</a></h3><p>In folgenden Fällen wird ein eingegebener Befehl abgelehnt und es erfolgt keine Änderung am Stimmzettel:</p><ul><li>Entspricht die Eingabe keinem unterstützten Format, enthält sie Leerzeichen oder verwendet sie keine positive ganze Anzahl.</li><li>Existiert die angegebene Ordnungszahl für den/die Kandidat*in oder den Wahlvorschlag nicht.</li><li>Ist ein Bereich größer als die vorhandene Kandidat*innenliste, oder umfasst er mehrere Wahlvorschläge.</li><li>Enthält ein Stimmenbereich mindestens eine gestrichene Nennung.</li><li>Sollen mehr Stimmen entfernt werden, als für die ausgewählte Nennung vorhanden sind.</li><li>Soll ein Listenkreuz erneut gesetzt oder von einem nicht ausgewählten Wahlvorschlag entfernt werden.</li><li>Soll eine Streichung erneut gesetzt oder zurückgenommen werden, obwohl keine Streichung vorhanden ist.</li></ul>',3))])}const S=d(h,[["render",u]]);export{w as __pageData,S as default};
